def transform(grid):
    # Infer a diagonal period from the repeating diagonal marker offsets,
    # then expand the color assigned to each offset across the grid.
    h, w = len(grid), len(grid[0])
    marks = {}
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v:
                marks[c-r] = v
    # Detect the offset period from repeated color/offset structure. Use the
    # most compact period that makes observed offsets consistent.
    offsets = sorted(marks)
    period = 0
    for p in range(1, max(h,w)+1):
        if len({o % p for o in offsets}) == len(offsets) and all(
            len({v for o,v in marks.items() if o % p == residue}) == 1
            for residue in {o % p for o in offsets}
        ):
            # Prefer a period yielding a dense sequence of residues.
            if len({o % p for o in offsets}) >= min(7, len(offsets)):
                period = p
                break
    if not period:
        period = max(offsets)-min(offsets)+1
    residue_color = {}
    for off, color in marks.items():
        residue_color[off % period] = color
    # Fill missing residues by cycling the ordered palette of diagonal marks.
    known = sorted(residue_color)
    for residue in range(period):
        if residue not in residue_color:
            nearest = min(known, key=lambda x: min((residue-x)%period,(x-residue)%period))
            residue_color[residue] = residue_color[nearest]
    return [[residue_color[(c-r)%period] for c in range(w)] for r in range(h)]
