def transform(grid):
    h, w = len(grid), len(grid[0])
    # A diagonal running down-right is identified by d = column - row.
    diagonal = {}
    valid = True
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                if d in diagonal and diagonal[d] != value:
                    valid = False
                diagonal[d] = value
    if valid and diagonal:
        # Find the smallest repeating diagonal period consistent with every
        # colored diagonal. Unmarked residues are the missing stripes.
        for period in range(1, max(h, w) + 1):
            residues = {}
            consistent = True
            for d, color in diagonal.items():
                residue = d % period
                if residue in residues and residues[residue] != color:
                    consistent = False
                    break
                residues[residue] = color
            if consistent and len(residues) == period:
                return [[residues[(c-r) % period] for c in range(w)] for r in range(h)]
    # For horizontal band examples, extend a repeated full-row color into
    # blank rows (the blank row wraps to a matching colored band).
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        if all(v == 0 for v in row):
            candidates = [grid[k] for k in range(h) if k != r and len(set(grid[k])) == 1 and grid[k][0] != 0]
            if candidates:
                out[r] = candidates[-1][:]
    return out
